from collections import deque
G=[[0,5,0,0,0,0,0,5,0,0,5,0],[0,5,0,0,0,5,5,5,0,5,5,0],[5,5,5,0,0,5,0,5,5,5,0,0],[0,0,5,5,5,5,0,5,0,5,5,0],[0,0,0,5,0,0,0,5,0,0,5,0]]
h,w=len(G),len(G[0]); seen=set(); q=deque()
for r in range(h):
 for c in range(w):
  if (r in (0,h-1) or c in (0,w-1)) and G[r][c]==0: seen.add((r,c));q.append((r,c))
while q:
 r,c=q.popleft()
 for x,y in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
  if 0<=x<h and 0<=y<w and G[x][y]==0 and (x,y) not in seen:seen.add((x,y));q.append((x,y))
inside=[(r,c) for r in range(h) for c in range(w) if G[r][c]==0 and (r,c) not in seen]
print(inside)

